# Demo: extend partial horizontal bar with color 1; full bar and background unchanged.
# input row [3,3,3,3,9,9,9,9] -> [3,3,3,3,1,1,1,1]
# For a different background, infer background as most frequent cell color.
def transform(grid):
    from collections import Counter
    bg = Counter(c for r in grid for c in r).most_common(1)[0][0]
    out = [r[:] for r in grid]
    for r in out:
        vals = [c for c in r if c != bg]
        if vals and len(vals) < len(r) and len(set(vals)) == 1:
            for j, c in enumerate(r):
                if c == bg:
                    r[j] = 1
    return out

if __name__ == '__main__':
    g = [[6]*8 for _ in range(15)]
    g[1] = [9]*4 + [6]*4
    g[10] = [9]*8
    print(transform(g))
